// Falls back to a single main number when no area-code match exists in the account's inventory
// (a small/starting number pool, or the lookup call itself failed/errored) - a call still goes out,
// just without the local-presence answer-rate boost, rather than blocking the dial entirely over a
// number-pool gap. Flagged, not silent: 'usedFallback' is passed through to the alert below so a
// thin number pool is visible, not just quietly degrading connect rates forever.
const response = $input.first().json;
const numbers = response?.data || (Array.isArray(response) ? response : []);
const match = Array.isArray(numbers) ? numbers[0] : null;

return [{
  json: {
    fromNumber: match?.phone_number || $env.TELNYX_DEFAULT_FROM_NUMBER || 'PLACEHOLDER_TELNYX_DEFAULT_FROM_NUMBER',
    usedFallback: !match,
  },
}];

// Telnyx echoes client_state back on every webhook event for this call leg - this is how
// telnyx-call-events-webhook.workflow.json correlates an async event back to hopper/CRM state
// without a second lookup table, per CRM-OBJECT-MODEL.md's HopperEntry notes on the two new Telnyx
// call-control-id fields. base64, matching Telnyx's own documented client_state encoding.
const webhookBody = $('Place call webhook').item.json.body;
const state = {
  role: 'customer',
  hopperEntryId: webhookBody.hopperEntryId,
  opportunityId: webhookBody.opportunityId,
  repId: webhookBody.repId,
  dialerMode: webhookBody.dialerMode,
};
return [{ json: { clientState: Buffer.from(JSON.stringify(state)).toString('base64') } }];

const webhookBody = $('Place call webhook').item.json.body;
const state = { role: 'agent', hopperEntryId: webhookBody.hopperEntryId, opportunityId: webhookBody.opportunityId, repId: webhookBody.repId };
return [{ json: { clientState: Buffer.from(JSON.stringify(state)).toString('base64') } }];
